static void rionet_remove_mport ( struct device * dev , struct class_interface * class_intf ) { struct rio_mport * mport = to_rio_mport ( dev ) ; struct net_device * ndev ; int id = mport -> id ; pr_debug ( "%s %s\n" , __func__ , mport -> name ) ; WARN ( nets [ id ] . nact , "%s called when connected to %d peers\n" , __func__ , nets [ id ] . nact ) ; WARN ( ! nets [ id ] . ndev , "%s called for mport without NDEV\n" , __func__ ) ; } 